const CACHE='__CACHE_NAME__';
const PREFIX='medpass-lab-';
const ASSETS=['./','./index.html','./app.js','./data.js','./dialog_engine.js','./styles.css','./icon.svg','./manifest.webmanifest'];
const CACHEABLE=new Set(['index.html','app.js','data.js','dialog_engine.js','styles.css','icon.svg','manifest.webmanifest']);
self.addEventListener('install',event=>{
  event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()));
});
self.addEventListener('activate',event=>{
  event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith(PREFIX)&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()));
});
self.addEventListener('fetch',event=>{
  if(event.request.method!=='GET')return;
  const url=new URL(event.request.url);
  const scope=new URL(self.registration.scope);
  if(url.origin!==scope.origin||!url.pathname.startsWith(scope.pathname))return;
  const pathname=url.pathname.slice(scope.pathname.length)||'index.html';
  if(!CACHEABLE.has(pathname))return;
  event.respondWith((async()=>{
    const cache=await caches.open(CACHE);
    try{
      const response=await fetch(event.request,{cache:'no-store'});
      if(response.ok)await cache.put(event.request,response.clone());
      return response;
    }catch(error){
      const cached=await cache.match(event.request);
      if(cached)return cached;
      if(event.request.mode==='navigate'){const fallback=await cache.match('./index.html');return fallback||Response.error();}
      return Response.error();
    }
  })());
});
